def _executive_html(html: str) -> str:
    """Add a self-contained reader layer without changing notebook semantics."""
    html = html.replace('<html lang="en">', '<html lang="es">')
    html = html.replace(
        '<script src="https://cdnjs.cloudflare.com/ajax/libs/require.js/2.1.10/require.min.js"></script>',
        "",
    )
    math_start = html.find("<!-- Load mathjax -->")
    math_end_marker = "<!-- End of mathjax configuration -->"
    math_end = html.find(math_end_marker, math_start)
    if math_start >= 0 and math_end >= 0:
        html = html[:math_start] + html[math_end + len(math_end_marker) :]
    module_start = html.find('<script type="module">')
    module_end = html.find("</script>", module_start)
    if module_start >= 0 and module_end >= 0 and "mermaid" in html[module_start:module_end]:
        html = html[:module_start] + html[module_end + len("</script>") :]
    return html.replace("</head>", EXECUTIVE_CSS + "</head>").replace(
        "</body>", EXECUTIVE_JS + "</body>"
    )


def build_notebook(settings: Settings) -> tuple[Path, Path]:
    root = settings.codexway_root
    if sys.platform == "win32" and hasattr(asyncio, "WindowsSelectorEventLoopPolicy"):
        asyncio.set_event_loop_policy(asyncio.WindowsSelectorEventLoopPolicy())
    runtime_root = root / "outputs" / "notebook_runtime"
    for name in ["ipython", "jupyter_config", "jupyter_data", "jupyter_runtime"]:
        (runtime_root / name).mkdir(parents=True, exist_ok=True)
    os.environ["IPYTHONDIR"] = str(runtime_root / "ipython")
    os.environ["JUPYTER_CONFIG_DIR"] = str(runtime_root / "jupyter_config")
    os.environ["JUPYTER_DATA_DIR"] = str(runtime_root / "jupyter_data")
    os.environ["JUPYTER_RUNTIME_DIR"] = str(runtime_root / "jupyter_runtime")

    notebook_dir = root / "notebooks"
    notebook_dir.mkdir(parents=True, exist_ok=True)
    prompt = (root / "llm" / "prompt.md").read_text(encoding="utf-8")
    md = nbformat.v4.new_markdown_cell
    code = nbformat.v4.new_code_cell

    cells = [
        md("# Spot2 · Lead Opportunity Score\n\n**Assessment end-to-end reproducible y auditable.** Este notebook no es un resumen decorativo: recorre fuentes canónicas, auditoría, EDA, contrato temporal, feature engineering, modelado, Inventory, fallback, Opportunity, IA, robustez y producción. Los anexos conservan el detalle exhaustivo; este notebook muestra la evidencia ejecutada que conecta todo el trabajo."),
        md("## 1. tl;dr — decisión ejecutiva\n\nEl objetivo no es automatizar una decisión comercial todavía. El resultado habilita una nueva cohorte *shadow* y, si se reproduce, un piloto aleatorizado con guardas."),
        code("from pathlib import Path\nimport json, pandas as pd, numpy as np, yaml\nimport matplotlib.pyplot as plt\nfrom IPython.display import display, Markdown, HTML, Image, SVG\nROOT = Path.cwd()\ndef read_json(path): return json.loads((ROOT/path).read_text(encoding='utf-8'))\nmodel = read_json(Path('outputs/metrics/t1_model_metrics.json'))\nsystem = read_json(Path('outputs/metrics/system_evaluation.json'))\nscores = pd.read_parquet(ROOT/'outputs/predictions/lead_opportunity_scores.parquet')\nassert model['selected_model'] == 'stable_segment_logistic'\nassert system['lead_quality_gate'] == 'GO'\nassert system['inventory_incremental_gate'] == 'NO_GO'\nassert system['decision'] == 'ELIGIBLE_FOR_NEW_FORWARD_VALIDATION_AND_GUARDED_RANDOMIZED_PILOT'\ndecision_label = 'Elegible para nueva validación forward y piloto aleatorizado con guardas'\nq, q_ci = system['quality_lift_top_10pct'], system['quality_lift_top_10pct_ci']\no, o_ci = system['opportunity_lift_top_10pct'], system['opportunity_lift_top_10pct_ci']\ndisplay(HTML(f'''<section class=\"spot2-hero\"><h3>Recomendación: validar hacia adelante</h3><p>{decision_label}</p></section><div class=\"spot2-grid\"><div class=\"spot2-card\"><strong>{q:.3f}×</strong><small>Quality Lift@10 · IC {q_ci[0]:.3f}–{q_ci[1]:.3f}</small></div><div class=\"spot2-card\"><strong>{o:.3f}×</strong><small>Opportunity lower Lift@10 · IC {o_ci[0]:.3f}–{o_ci[1]:.3f}</small></div><div class=\"spot2-card\"><strong>{model['selected_model']}</strong><small>modelo seleccionado · calibración Platt retenida</small></div><div class=\"spot2-card\"><strong>{system['inventory_incremental_gate'].replace('_','-')}</strong><small>valor incremental de Inventory sobre T1</small></div></div>'''))"),
        md("<div class=\"spot2-callout\"><strong>Qué demuestra.</strong> En el holdout procedural, Quality y Opportunity lower superan la selección aleatoria absoluta en el top 10%. <strong>Qué no demuestra.</strong> Inventory no agrega valor incremental probado sobre Quality y el target T1 no observa el éxito del fallback.</div>"),
        md("### 1.1 Mapa del trabajo ejecutado\n\nEste artefacto funciona como **hilo conductor técnico de toda la solución**, no como sustituto de los anexos. El recorrido reproducible es:\n\n1. **Lectura de fuentes:** seis tablas canónicas Parquet, con CSV como control de equivalencia.\n2. **Auditoría:** llaves, grano, timestamps, missingness, duplicados y relaciones.\n3. **EDA:** composición de demanda, target por segmento, temporalidad, mercado, disponibilidad, candidate depth y perfiles.\n4. **Contrato temporal:** T0/T1/T2, madurez del target, censura y matriz explícita de leakage.\n5. **ABT point-in-time:** una fila por lead en T1, allowlist/denylist y transformaciones determinísticas.\n6. **Lead Quality:** baselines, challengers, rolling temporal CV, calibración, ranking por capacidad, estabilidad y error analysis.\n7. **Inventory:** candidate generation, Availability backward-as-of, frescura, incertidumbre y bounds lower/upper.\n8. **Fallback:** top-3 interno para serviceability, hasta cinco alternativas visibles, reason codes y NO_RESULT.\n9. **Opportunity:** combinación conservadora de Quality × Inventory, comparación contra Quality-only y gates.\n10. **Robustez e IA:** stress tests, clustering gobernado, resultados negativos y Catalog QA con LLM.\n11. **Producción:** scoring contract, monitoreo, rollback, shadow validation y protocolo RCT.\n12. **Trazabilidad:** cada claim principal apunta a outputs, tablas, evidencia o entregables finales.\n\n**Regla de lectura:** una conclusión sólo aparece aquí si está respaldada por una celda ejecutada o por un artefacto canónico generado por el pipeline.\n"),
        md("## 2. Contexto y contrato analítico\n\n### 2.1 Problema de negocio y momentos de scoring\n\nT0 es una sensibilidad *cold-start* al crear el lead. **T1 es el contrato primario:** un score por lead en su primera solicitud, después de observar la demanda y antes de la respuesta del broker. T2 es un challenger para solicitudes posteriores usando sólo payloads previos."),
        code("manifest = read_json(Path('outputs/abt/split_manifest.json'))\ndisplay(pd.DataFrame(manifest['partitions']).T)"),
        md("### 2.2 Auditoría y granularidad\n\nCSV y Parquet son representaciones duplicadas, no observaciones adicionales. Parquet es canónico. Llaves, esquema, timestamps e igualdad entre formatos son verificaciones ejecutables."),
        code("audit = read_json(Path('outputs/tables/data_audit.json'))\ndisplay(pd.DataFrame(audit['tables']).T if isinstance(audit.get('tables'), dict) else audit)"),
        md("### 2.2.1 Inventario de datos antes de modelar\n\nLa lectura parte del grano real de cada fuente. No se mezclan tablas por comodidad: primero se define qué representa cada registro y qué reloj gobierna su uso.\n\n| Fuente | Filas | Grano / rol |\n|---|---:|---|\n| leads | 5,000 | una necesidad inicial por lead; intake observable desde T0 |\n| inquiries | 22,576 | eventos lead–spot; en T1 sólo se usa la primera inquiry y su payload contemporáneo |\n| spots | 3,000 | catálogo de listings; varios campos son estado mutable actual, no historia versionada |\n| spot_attributes | 3,000 | atributos físicos 1:1 del spot |\n| availability_snapshot | 30,000 | historia temporal 1:N por spot; exige join backward-as-of |\n| market_context | 500 | agregado geografía × sector × mes; útil para EDA, no para el modelo limpio sin publication time |\n\nLa limpieza relacional es alta: 0 duplicados de PK en las tablas canónicas y 0 huérfanos en las relaciones críticas auditadas. El riesgo principal no está en “arreglar datos rotos”, sino en **usar datos correctos en el momento equivocado**.\n"),
        md("### 2.3 Lectura directa de las seis fuentes canónicas\n\nEl notebook vuelve a leer las seis tablas Parquet canónicas y deja visible su grano y tamaño. Los CSV se usan únicamente como control de equivalencia; nunca se concatenan con Parquet.\n"),
        code("DATA = ROOT.parent/'data'/'candidate'/'parquet'\nCSV_DATA = ROOT.parent/'data'/'candidate'/'csv'\nraw_names = ['leads','inquiries','spots','spot_attributes','availability_snapshot','market_context']\nraw = {name: pd.read_parquet(DATA/f'{name}.parquet') for name in raw_names}\ninventory = pd.DataFrame({name: {'rows': len(df), 'columns': df.shape[1]} for name, df in raw.items()}).T\ndisplay(inventory)\ndisplay(raw['leads'].head(3)); display(raw['inquiries'].head(3)); display(raw['spots'].head(3))\n"),
        md("### 2.4 Equivalencia CSV ↔ Parquet, llaves y missingness\n\nLa duplicidad de formatos era una trampa potencial. La revisión comprueba equivalencia de filas/columnas y muestra la ausencia de datos antes de definir target o features.\n"),
        code("equiv = []\nfor name in raw_names:\n    csv_df = pd.read_csv(CSV_DATA/f'{name}.csv')\n    pq_df = raw[name]\n    equiv.append({'table': name, 'rows_parquet': len(pq_df), 'rows_csv': len(csv_df),\n                  'same_rows': len(pq_df)==len(csv_df),\n                  'same_columns': set(pq_df.columns)==set(csv_df.columns)})\ndisplay(pd.DataFrame(equiv))\nmissing = pd.read_csv(ROOT/'outputs/tables/data_quality_missingness.csv')\ndisplay(missing.head(35))\n"),
        md("### 2.4.1 Calidad de datos que sí cambió la arquitectura\n\nTres hallazgos de calidad de datos alteraron directamente el diseño:\n\n- **Join explosion:** unir inquiries con Availability sólo por spot_id expande 22,576 inquiries a 226,151 filas, aproximadamente **10.017×**. El grano deja de ser lead/inquiry.\n- **Fuga temporal:** escoger el snapshot “más cercano” haría que **7,758 inquiries (34.36%)** recibieran información de un snapshot futuro.\n- **Missingness semántico:** ausencia de presupuesto, urgencia o cobertura de Availability no siempre significa cero/no; se distinguen estados como desconocido, no aplicable y stale.\n\nPor eso el pipeline separa auditoría, feature policy e Inventory. La ausencia de observación se conserva como información y no se rellena con el futuro.\n"),
        md("### 2.5 Target, madurez y censura\n\nEl proxy primario es `scheduled_visit` en la primera solicitud. Siete días es el buffer de madurez por defecto. Filas sin seguimiento suficiente conservan `target = NA`; nunca se convierten silenciosamente en negativas."),
        code("maturity = pd.read_csv(ROOT/'outputs/tables/target_maturity_sensitivity.csv')\ntarget_metrics = pd.read_csv(ROOT/'outputs/metrics/target_sensitivity_metrics.csv')\nassert 7 in maturity.select_dtypes('number').astype(float).values\ndisplay(maturity); display(target_metrics.round(4)); display(Image(filename=str(ROOT/'outputs/figures/target_drift.png')))"),
        md("### 2.5.1 Target: qué predice realmente el sistema\n\nEl target final de Codexway es **scheduled_visit en la primera inquiry**, no cierre, revenue ni aceptación de fallback. Es un proxy temprano de progreso comercial elegido porque es observable con un contrato temporal defendible.\n\nCon madurez de siete días:\n\n- **4,898** T1 maduros;\n- **1,001** positivos;\n- prevalencia **20.44%**;\n- **102** leads recientes quedan censurados y no se fuerzan a negativo.\n\nLa sensibilidad de madurez es estable: la prevalencia permanece alrededor de 20.4% al mover el buffer de 7 a 14 o 30 días. Esto reduce el riesgo de que el resultado dependa de un cutoff conveniente, pero no elimina la limitación conceptual: optimizamos progreso temprano, no valor económico final.\n"),
        md("### 2.6 Política de leakage\n\nLa allowlist excluye respuesta del broker, horas de respuesta, score interno, solicitudes futuras, contadores mutables, contexto de mercado ambiguo y snapshots más cercanos o futuros. Una señal entra sólo si era demostrablemente observable al momento del score."),
        code("display(Markdown((ROOT/'evidence/LEAKAGE_MATRIX.md').read_text(encoding='utf-8')))"),
        md("## 3. Datos y tensión demanda–oferta\n\n### 3.1 Mezcla, volumen y segmentos\n\nLa lectura comienza con la composición de demanda y su evolución temporal. Las diferencias por segmento son descriptivas: no implican causalidad y deben vigilarse por tamaño y estabilidad."),
        code("display(Image(filename=str(ROOT/'outputs/figures/eda_lead_mix.png')))\ndisplay(Image(filename=str(ROOT/'outputs/figures/eda_monthly_volume.png')))\ndisplay(Image(filename=str(ROOT/'outputs/figures/eda_target_segments.png')))\ndisplay(pd.read_csv(ROOT/'outputs/tables/target_rate_by_segment.csv').sort_values(['segment','n'], ascending=[True,False]).head(20))"),
        md("### 3.1.1 Qué mostró el EDA de demanda\n\nLa demanda es amplia y no existe una sola “persona Spot2”:\n\n- **Sector:** Retail 30.56%, Office 29.00%, Industrial 24.98%, Land 15.46%.\n- **Modalidad:** rent 50.06%, sale 29.80%, both 20.14%.\n- **Tipo de usuario:** tenant_direct 39.12%, intermediario 36.08%, investor 19.94%, developer 4.86%.\n- **Adquisición:** organic 29.26%, paid 24.92%, referral 20.34%, con el resto distribuido entre social, email y event.\n\nEn DEVELOPMENT, Retail también aparece con mayor presión relativa frente al catálogo histórico: **30.40% de demanda vs 24.51% de catálogo (+5.89 pp; índice ≈1.24×)**. Esto es una señal de tensión relativa, no una prueba de serviceability: todavía faltan disponibilidad, área, precio, geografía y vigencia.\n\nLa primera inquiry además **refina la necesidad**. Ese hallazgo es una de las razones por las que T1 es el momento principal de scoring.\n"),
        md("### 3.2 Contexto de mercado: narrativa, no feature\n\n`market_context.month` no tiene timestamp fiable de publicación o vigencia. Sirve para entender el entorno, pero no es admisible como feature histórica."),
        code("display(Image(filename=str(ROOT/'outputs/figures/eda_market_context.png')))\ndisplay(pd.read_csv(ROOT/'outputs/tables/market_context_eda.csv'))"),
        md("### 3.3 Clustering por entidad: qué estructura latente existe en los datos\n\nEl clustering se usa aquí como **herramienta de EDA y descubrimiento de perfiles**, no como variable objetivo ni como regla de priorización. La línea experimental comparó K-Means, Bisecting K-Means, BIRCH y Gaussian Mixture entre K=3 y K=7; la selección fue **resultado-free** y combinó separación, balance y estabilidad. Los perfiles se aprendieron en una ventana temprana y se congelaron antes del tramo predictivo para evitar look-ahead.\n\n| Entidad / faceta | Solución descriptiva | Qué separa | Lectura |\n|---|---:|---|---|\n| Lead | K-Means, 6 perfiles | geografía preferida e historial de búsquedas | el lead no es homogéneo: ubicación y madurez de búsqueda forman grupos claros |\n| Lead Persona | Bisecting, 7 perfiles | canal de adquisición + historia | útil para describir origen/madurez; no implica calidad causal |\n| Search Need | K-Means, 3 perfiles | renta, venta y modalidad flexible/both | confirma que **quién es** y **qué necesita** son facetas distintas |\n| Spot | Bisecting, 7 perfiles | geografía y atributos físicos | motivó separar después **Physical Space** y **Location** |\n| Broker | Bisecting, 7 perfiles | mezcla de regiones/modalidades y comportamiento histórico | aporta segmentación, pero no justifica routing automático |\n| Inquiry Intent | K-Means, 7 perfiles | casi exclusivamente día de la semana | técnicamente estable, pero semánticamente pobre; se descarta como representación final |\n\nTodos los clusterers seleccionados en v2 pasaron el gate de balance (cluster mínimo ≥5% y máximo ≤70%). El resultado importante no es el ID numérico del cluster, sino **qué dimensiones del problema aparecen de forma consistente**.\n"),
        code("from pathlib import Path\nimport matplotlib.pyplot as plt\n\nEXPERIMENTS_ROOT = ROOT.parent / 'experimentos'\nif not EXPERIMENTS_ROOT.exists():\n    EXPERIMENTS_ROOT = ROOT / 'experimentos'\n\nV2 = EXPERIMENTS_ROOT / 'profile_clustering_v2' / 'results'\nclusterers_v2 = pd.read_csv(V2 / 'selected_clusterers.csv')\nprofiles_v2 = pd.read_csv(V2 / 'profile_interpretability.csv')\n\ncluster_summary = (\n    clusterers_v2.loc[:, [\n        'profile_family','method','k','silhouette',\n        'min_cluster_share','max_cluster_share','stability_ari','balance_ok'\n    ]]\n    .rename(columns={\n        'profile_family':'familia',\n        'method':'método',\n        'silhouette':'silhouette',\n        'min_cluster_share':'share_mín',\n        'max_cluster_share':'share_máx',\n        'stability_ari':'ARI_estabilidad',\n        'balance_ok':'balance_ok'\n    })\n)\ndisplay(cluster_summary.round(3))\n\n# Interpretabilidad completa: permite inspeccionar todos los perfiles, no sólo ejemplos escogidos.\ndisplay(\n    profiles_v2[['profile_family','profile_id','n_reference','share_reference','top_signals']]\n    .sort_values(['profile_family','share_reference'], ascending=[True,False])\n    .reset_index(drop=True)\n)\n\n# Distribución de perfiles por familia.\nfor family, g in profiles_v2.groupby('profile_family', sort=False):\n    fig, ax = plt.subplots(figsize=(7, 2.8))\n    gg = g.sort_values('share_reference')\n    ax.barh(gg['profile_id'], gg['share_reference'])\n    ax.set_title(f'{family}: peso de cada perfil en calibración')\n    ax.set_xlabel('share de referencia')\n    ax.set_ylabel('perfil')\n    plt.tight_layout()\n    plt.show()\n"),
        md("### 3.4 Refinamiento semántico: separar persona, necesidad, espacio, ubicación y servicio\n\nEl experimento posterior `matching_profiles_v4` tomó la estructura anterior y la hizo más útil para negocio. La mejora conceptual más importante fue **dejar de pedirle a un solo cluster que represente demasiadas cosas a la vez**:\n\n- **Lead / Behavioral Persona (BP1–BP3):** separa madurez e historia. BP3 es el lead más experimentado, con alta conversión previa e historial de inquiries.\n- **Search Need T0 (N1–N3):** renta, venta y flexible/both.\n- **Dynamic Need T1 (DN1–DN5):** actualiza la necesidad cuando ya existe una inquiry. DN4 es el perfil *stretch-space*: solicita mucho más espacio con presupuesto relativamente bajo.\n- **Spot:** se descompone en **Physical Space (PH1–PH4)** y **Location (LOC1–LOC7)**; esta separación es más interpretable que un Spot cluster único.\n- **Broker Service (BSV1–BSV3):** sí produce grupos balanceados y estables. BSV1 representa servicio más diversificado/mayor actividad; BSV2 acceptance-heavy; BSV3 mayor urgencia/orientación a calendarizar.\n- **Broker Supply:** se intentó dos veces y se **rechazó**. La solución compacta quedó 70.3% / 26.0% / 3.7%, violando el gate 5%–65%. Forzar otro K habría fabricado segmentación.\n- **Inquiry Intent:** se descarta porque aprendía weekday.\n- **Availability:** no se clusteriza; es un estado temporal directo y debe conservar su significado operativo.\n\nUna señal especialmente útil del EDA es la transición T0→T1: el perfil de renta N1 permanece en DN1 en **99.82%** de los casos, mientras venta y flexible se redistribuyen. La información nueva de T1 está, por tanto, concentrada en los casos donde la necesidad comercial realmente se refina.\n"),
        code("V4 = EXPERIMENTS_ROOT / 'matching_profiles_v4' / 'results'\nclusterers_v4 = pd.read_csv(V4 / 'selected_clusterers.csv')\nprofiles_v4 = pd.read_csv(V4 / 'profile_interpretability.csv')\ntransition_v4 = pd.read_csv(V4 / 'need_t0_t1_transition_matrix.csv')\n\ndisplay(\n    clusterers_v4[[\n        'profile_family','method','k','silhouette',\n        'stability_ari','min_cluster_share','max_cluster_share','balance_ok'\n    ]].round(3)\n)\n\n# Perfiles v4 relevantes para lectura de negocio.\ndisplay(\n    profiles_v4[\n        profiles_v4['profile_family'].isin([\n            'behavioral_persona','dynamic_need_t1','broker_service_balanced'\n        ])\n    ][['profile_family','profile_id','n_reference','share_reference','top_signals']]\n    .reset_index(drop=True)\n)\n\ndisplay(Markdown('**Transición Search Need T0 → Dynamic Need T1**'))\ndisplay(transition_v4)\n"),
        md("### 3.5 Combinaciones poderosas: dónde aparecieron pockets de compatibilidad\n\nAl cruzar los perfiles surgieron **pockets locales con tasas de visita muy superiores al baseline histórico (~20.77%)**. Éstos son los hallazgos más fuertes de `matching_profiles_v4`:\n\n| Rank | Combinación | N | Visita raw | Tasa suavizada | Lift histórico | Wilson lower / baseline |\n|---:|---|---:|---:|---:|---:|---:|\n| 1 | **DN4 × LOC1 × BSV1** | 60 | **36.67%** | **31.37%** | **1.510×** | **1.234×** |\n| 2 | **N3→DN4 × BSV1** | 83 | 31.33% | 28.52% | **1.373×** | **1.077×** |\n| 3 | N2→DN2 × BSV3 | 57 | 31.58% | 27.85% | 1.341× | 1.011× |\n| 4 | **DN4 × LOC1** | 90 | 30.00% | 27.69% | **1.333×** | **1.036×** |\n| 5 | DN2 × PH1 × BSV3 | 59 | 30.51% | 27.23% | 1.311× | 0.975× |\n| 6 | PH3 × BSV2 | 159 | 28.30% | 27.11% | **1.305×** | **1.053×** |\n| 7 | **DN4 × BSV1** | 153 | 28.10% | 26.90% | **1.295×** | **1.039×** |\n| 8 | DN2 × BSV3 | 90 | 28.89% | 26.86% | 1.293× | 0.989× |\n\nLa celda más llamativa combina:\n\n- **DN4:** necesidad *stretch-space* — busca mucho más espacio con presupuesto relativamente bajo;\n- **LOC1:** ubicación centro metropolitano CDMX–Naucalpan;\n- **BSV1:** broker con servicio diversificado y mayor actividad.\n\nTambién en la versión v2 aparecieron interacciones Lead × Spot × Broker con lift local >1.3×, por ejemplo **L1 × S1 × B5 (N=93, lift 1.314×)** y **L1 × S5 × B2 (N=35, lift 1.304×)**. Esto reforzó la hipótesis de que la compatibilidad entre entidades contiene señal que los marginales no capturan completamente.\n\n> **Cautela metodológica:** “poderosa” significa *prometedora para investigación*, no *lista para producción*. Estas celdas fueron descubiertas inspeccionando el mismo future test y hubo múltiples comparaciones. Por eso no se multiplica el Opportunity Score por 1.51 ni se convierte DN4 × LOC1 × BSV1 en hard routing. En la confirmación gobernada final de Codexway, ninguna celda elegible justificó promoción tras corrección por multiplicidad. El valor del hallazgo es generar una hipótesis concreta para una nueva cohorte temporal o un A/B sticky por `lead_id`.\n"),
        code("top_v4 = pd.read_csv(V4 / 'top_service_compatibility_cells.csv')\n\ndef combo_label(r):\n    parts = []\n    if pd.notna(r.get('need_transition')) and str(r.get('need_transition')).strip():\n        parts.append(str(r['need_transition']))\n    if pd.notna(r.get('dynamic_need_profile')) and str(r.get('dynamic_need_profile')).strip():\n        parts.append(str(r['dynamic_need_profile']))\n    if pd.notna(r.get('physical_profile')) and str(r.get('physical_profile')).strip():\n        parts.append(str(r['physical_profile']))\n    if pd.notna(r.get('location_profile')) and str(r.get('location_profile')).strip():\n        parts.append(str(r['location_profile']))\n    if pd.notna(r.get('broker_service_balanced_profile')) and str(r.get('broker_service_balanced_profile')).strip():\n        parts.append(str(r['broker_service_balanced_profile']))\n    return ' × '.join(parts)\n\ntop_show = top_v4.head(12).copy()\ntop_show['combinación'] = top_show.apply(combo_label, axis=1)\ndisplay(\n    top_show[[\n        'combinación','interaction','n','visit_rate','smoothed_rate',\n        'lift_vs_global','wilson_low_lift'\n    ]].rename(columns={\n        'interaction':'tipo_interacción',\n        'visit_rate':'tasa_visita_raw',\n        'smoothed_rate':'tasa_suavizada',\n        'lift_vs_global':'lift_vs_global',\n        'wilson_low_lift':'wilson_lower_vs_baseline'\n    }).round(3)\n)\n\nfig, ax = plt.subplots(figsize=(8, 4.5))\nplot_df = top_show.head(8).sort_values('lift_vs_global')\nax.barh(plot_df['combinación'], plot_df['lift_vs_global'])\nax.axvline(1.0, linestyle='--', linewidth=1)\nax.set_xlabel('lift histórico vs baseline')\nax.set_ylabel('combinación')\nax.set_title('Pockets exploratorios de compatibilidad — matching_profiles_v4')\nplt.tight_layout()\nplt.show()\n\n# Referencia v2: primeras combinaciones Lead × Spot × Broker por sinergia residual.\ncomb_v2 = pd.read_csv(V2 / 'top_3entity_combinations.csv')\ndisplay(\n    comb_v2[[\n        'lead_profile','spot_profile','broker_profile','n',\n        'scheduled_visit_rate','smoothed_visit_rate',\n        'lift_vs_global','residual_synergy','wilson_low','wilson_high'\n    ]].head(10).round(3)\n)\n"),
        md("### 3.6 EDA integrado: hallazgos que cambiaron la solución\n\nEl EDA final integró Codexway, experimentos y AssessmentSol1 sin sustituir la arquitectura ganadora. Se recuperan sólo los hallazgos que cambiaron una decisión técnica u operativa.\n"),
        code("eda_metrics = pd.read_csv(ROOT.parent/'entregable/01_eda/tablas/01_metricas_eda_clave.csv')\nfocus_topics = ['Contrato T1','Demanda vs oferta','Refinamiento','Datos faltantes','Exposición','Inventario','Disponibilidad','Vigencia','Compatibilidad']\ndisplay(eda_metrics[eda_metrics['tema'].isin(focus_topics)].reset_index(drop=True))\n"),
        md("### 3.7 Evidencia visual del EDA final\n\nOcho gráficos condensan las decisiones que más importan para el modelo y el sistema.\n"),
        code("eda_fig_dir = ROOT.parent/'entregable/01_eda/figuras'\neda_gallery = [\n ('01_demanda_vs_oferta_sector.svg','Demanda vs oferta por sector'),\n ('02_target_vs_coverage_temporal.svg','Target y cobertura cambian con el tiempo'),\n ('03_candidate_depth_temporal.svg','La profundidad de candidatos deriva'),\n ('04_refinamiento_area.svg','La primera consulta refina la necesidad'),\n ('09_join_availability_leakage.svg','Nearest availability puede mirar al futuro'),\n ('14_unknown_no_es_unavailable.svg','UNKNOWN no es UNAVAILABLE'),\n ('16_no_estacionariedad_clocks.svg','No estacionariedad de múltiples clocks'),\n ('22_quality_inventory_quadrant.svg','Quality e Inventory son dos ejes distintos'),\n]\nfor filename, caption in eda_gallery:\n    path = eda_fig_dir/filename\n    assert path.exists(), path\n    display(Markdown(f'**{caption}**'))\n    display(SVG(filename=str(path)))\n"),
        md("### 3.8 De EDA a decisiones de ingeniería\n\n- T1 gana a T0 porque la consulta aporta información nueva.\n- UNKNOWN no es UNAVAILABLE: incertidumbre y vigencia sobreviven al scoring.\n- market_context permanece EDA_ONLY por ausencia de publication time.\n- Conteos futuros y estado mutable del listing quedan fuera del modelo limpio.\n- Los pockets de clusters quedan como hipótesis: 0/19 celdas pasan BH-FDR 10% en confirmación.\n"),
        md("### 3.9 Registro de hipótesis del EDA\n\nEl EDA no se cerró con una colección de gráficas; cada hallazgo se convirtió en una decisión o en una hipótesis gobernada.\n\n| Hipótesis | Evidencia | Estado / consecuencia |\n|---|---|---|\n| T1 aporta información adicional frente a T0 | refinamiento del request y sensibilidades T0/T1/T2 | **Soportada** → T1 canónico |\n| Availability puede tratarse como estado actual | coverage/freshness drift y 34.36% de riesgo con nearest snapshot | **Rechazada** → backward-as-of |\n| UNKNOWN equivale a UNAVAILABLE | missing/stale Availability | **Rechazada** → bounds + confidence |\n| Market Context puede entrar directo al modelo | no existe publication time fiable | **Rechazada** → EDA_ONLY |\n| Candidate depth es una señal estable de lead | cambia materialmente con el tiempo | **Rechazada** para Quality → pertenece a Inventory |\n| Pockets de clusters pueden convertirse en reglas | lifts locales altos, pero múltiples comparaciones | **Inconclusa** → hipótesis para nueva cohorte |\n| La compatibilidad entre entidades contiene estructura | perfiles y combinaciones interpretables | **Soportada descriptivamente**, no como multiplicador |\n| Un modelo más complejo debe ganar por defecto | challengers complejos no dominaron estabilidad + top-decile | **Rechazada** → champion simple y estable |\n\nEste registro explica por qué varias ideas interesantes terminan **fuera** del score final: investigar algo y no promoverlo es parte del trabajo, no trabajo perdido.\n"),
        md("## 4. ABT y feature engineering point-in-time\n\nEl modelado empieza sólo después de congelar el reloj. La ABT T1 mantiene un registro por lead en su primera inquiry y separa intake, payload contemporáneo y transformaciones determinísticas T0→T1.\n"),
        code("abt_t1 = pd.read_parquet(ROOT/'outputs/abt/abt_t1_first_inquiry.parquet')\npolicy = yaml.safe_load((ROOT/'config/feature_policy.yaml').read_text(encoding='utf-8'))['clean_t1']\nsummary = {'rows': len(abt_t1), 'columns': abt_t1.shape[1],\n           'target_observed': int(abt_t1['target'].notna().sum()),\n           'target_positive': int((abt_t1['target']==1).sum()),\n           'allow_features': len(policy['allow']),\n           'forbidden_features': len(policy['forbidden'])}\ndisplay(pd.Series(summary, name='ABT T1'))\ndisplay(pd.DataFrame({'allow': pd.Series(policy['allow']), 'forbidden': pd.Series(policy['forbidden'])}))\n"),
        md("### 4.0.1 Grano final de la ABT y separación de responsabilidades\n\nLa ABT T1 tiene **una fila por lead en su primera inquiry**. Conserva lead/inquiry, prediction_timestamp, intake, payload contemporáneo, transforms determinísticos y target sólo para evaluación.\n\n**Spot state y Availability no forman parte de Lead Quality**: se reservan para Inventory y Opportunity. Esto evita double counting de matching y mantiene separadas propensión comercial y capacidad de atención.\n"),
        md("### 4.1 Features derivadas y consistencia T0→T1\n\nLas transformaciones priorizan semántica y reproducibilidad: ratios de área/presupuesto, días desde creación, missingness y una interacción estable de baja cardinalidad. No se promueven variables por correlación aislada.\n"),
        code("derived = ['days_from_lead_creation','area_request_to_target_ratio',\n           'rent_request_to_lead_budget_ratio','sale_request_to_lead_budget_ratio',\n           'industrial_small_or_paid_interaction']\navailable = [c for c in derived if c in abt_t1.columns]\ndisplay(abt_t1[['lead_id','inquiry_id','target'] + available].head(12))\n"),
        md("### 4.1.1 Contrato de features: qué entra y qué queda fuera\n\nLa feature policy usa allowlist/forbidden list.\n\n**Puede entrar:** intake conocido, payload de la primera inquiry, días desde creación, ratios área/presupuesto, missingness semántico e interacciones de baja cardinalidad validadas temporalmente.\n\n**No puede entrar:** respuesta del broker, inquiries futuras, scores internos, nearest/future Availability, estado mutable actual del listing tratado como historia, Market Context sin publication time, ni variables T2 dentro del scorer T1.\n\nLa regla es más estricta que “no usar el target”: **cada feature debe demostrar observabilidad al score_time**.\n"),
        md("### 4.2 T0 y T2 como sensibilidades, no como mezcla de scores\n"),
        code("display(read_json(Path('outputs/metrics/t0_t2_sensitivity_metrics.json')))\n"),
        md("## 5. Lead Quality — selección, ranking y calibración\n\n### 5.1 Baselines antes de complejidad\n\nTasa positiva, una regla interpretable y Regresión Logística preceden a CatBoost. La promoción usa folds temporales expansivos; el holdout no participa en la selección."),
        code("display(pd.DataFrame(model['metrics']).T.round(4))\ndisplay(pd.read_csv(ROOT/'outputs/metrics/rolling_model_comparison.csv').round(4))"),
        md("### 5.1.1 Benchmark canónico y amplitud experimental\n\n| Modelo | ROC-AUC | PR-AUC | Brier | Lift@10 |\n|---|---:|---:|---:|---:|\n| Positive rate | 0.5000 | 0.2122 | 0.1672 | 1.000× |\n| Business rule | 0.5157 | 0.2165 | 0.2501 | 0.986× |\n| Logistic lead-only | 0.4823 | 0.2098 | 0.1733 | 0.932× |\n| Logistic clean amplio | 0.4881 | 0.2156 | 0.1744 | 0.850× |\n| Logistic sin asked_visit | 0.4852 | 0.2152 | 0.1743 | 0.987× |\n| CatBoost | 0.4922 | 0.2086 | 0.2423 | 0.826× |\n| **Stable segment logistic** | **0.5478** | **0.2391** | **0.1655 raw** | **1.689×** |\n| **Selected calibrated** | **0.5478** | **0.2391** | **0.1658** | **1.689×** |\n\nAdemás se investigaron especialistas CatBoost/RF, multi-head, trajectory T2, Dynamic Need, clusters, matching profiles y semantic rules bajo otros contratos experimentales. Sirven como evidencia de investigación, no como un leaderboard mezclado.\n\nLa conclusión final: **más variables y más complejidad no produjeron un ranking mejor bajo el contrato limpio T1**.\n"),
        md("### 5.1.2 Rolling temporal CV y gate de promoción\n\n| Fold | Lift@10 |\n|---|---:|\n| 1 | 0.784× |\n| 2 | 1.443× |\n| 3 | 1.753× |\n| 4 | 0.875× |\n\nMedia **1.214×**, mediana **1.159×**, 2/4 folds >1.\n\nEl gate exige media y mediana >1, al menos 2/4 folds >1, Lift@10 de validation >1 y Brier no materialmente peor al baseline constante. En validation: Lift@10 **1.442×**, Brier **0.15611** vs baseline **0.15691**.\n\nPasa el gate, pero no todos los folds ganan. El holdout 2026 es **procedural, no pristine**, por lo que la confirmación real requiere nueva cohorte forward.\n"),
        md("### 5.1.3 Champion final: simple, deliberadamente de baja resolución\n\nEl modelo final es una **Regresión Logística regularizada** con la interacción:\n\nindustrial_small_or_paid_interaction = Industrial AND (company_size = small OR source = paid).\n\nCoeficiente estandarizado: **+0.1204**.\n\nSe promueve por baja cardinalidad, observabilidad, menor superficie de leakage, concentración operativa y facilidad de monitoreo. Después de Platt, el holdout contiene esencialmente dos scores: **0.187899** y **0.253098**.\n\nEs gobernable, pero de baja resolución. El notebook no debe fingir granularidad que el modelo no posee.\n"),
        md("### 5.2 Ranking bajo capacidad limitada\n\nRecall@X responde la pregunta operativa: ¿qué proporción de resultados positivos aparece al trabajar sólo el X% superior de leads?"),
        code("display(Image(filename=str(ROOT/'outputs/figures/gains_curve.png')))\ngains = pd.read_csv(ROOT/'outputs/tables/gains.csv')\ndisplay(gains.query('population_fraction in [0.05, 0.1, 0.2]').round(4))"),
        md("### 5.2.1 Política capacity-first y empates\n\n| Capacidad | Precision | Recall | Lift |\n|---:|---:|---:|---:|\n| 5% | 35.83% | 8.49% | **1.689×** |\n| 10% | 35.83% | **16.98%** | **1.689×** |\n| 20% | 28.37% | 26.80% | **1.337×** |\n\nLa política final usa top **10%** por defecto, con escenarios 5/10/20%. El threshold de validation P90 ≈ **0.253098** no es una frontera universal de “buen lead”.\n\nComo existen empates, las métricas son **tie-aware**: el corte usa captura esperada fraccional y no depende del orden físico de filas.\n"),
        md("### 5.3 Calibración e incertidumbre\n\nLa calibración Platt se ajusta en validación y se conserva sólo si mejora. Los intervalos bootstrap separan una señal plausible de una falsa precisión puntual."),
        code("display(Image(filename=str(ROOT/'outputs/figures/calibration_plot.png')))\ndisplay(pd.read_csv(ROOT/'outputs/metrics/t1_metric_intervals.csv').round(4))"),
        md("### 5.3.1 Calibración: se retiene, pero no se sobrevende\n\nPlatt scaling sobre validation mejora marginalmente:\n\n- Brier: 0.1561106 → **0.1560762**\n- Log Loss: 0.4909444 → **0.4908026**\n\nEn holdout, Brier = **0.16577** frente a baseline 0.16725; skill ≈ **0.0088**.\n\nLa banda alta está subcalibrada: predicción media 0.2531 vs tasa observada 0.3583. Por eso el score sirve para ranking, pero no debe venderse como probabilidad económica definitiva.\n"),
        md("### 5.4 Interpretabilidad y estabilidad temporal"),
        code("display(pd.read_csv(ROOT/'outputs/tables/feature_importance.csv').head(20))\ndisplay(pd.read_csv(ROOT/'outputs/tables/monthly_model_stability.csv').round(4))\ndisplay(pd.read_csv(ROOT/'outputs/tables/feature_drift.csv').sort_values('value', ascending=False).head(20))"),
        md("### 5.4.1 Estabilidad temporal: señal útil, heterogeneidad real\n\nLift@10 mensual 2026: Enero 1.207×, Febrero 1.281×, Marzo 2.554×, Abril 1.432×, Mayo 1.650×, Junio 1.823×.\n\nTodos los meses quedan >1, pero marzo es atípico y los folds rolling no son uniformes. Esto obliga a monitorear prevalence, Lift/Recall@K, Brier, distribución del segmento Industrial-small/paid y drift de la feature final.\n"),
        md("### 5.5 Error analysis y desempeño por segmento\n\nEl análisis no termina en una métrica agregada. Se revisan errores y segmentos para detectar soporte pequeño, degradación localizada y posibles artefactos temporales.\n"),
        code("display(pd.read_csv(ROOT/'outputs/tables/error_analysis.csv').head(30))\ndisplay(pd.read_csv(ROOT/'outputs/tables/segment_metrics.csv').round(4).head(40))\n"),
        md("### 5.5.1 Error analysis: dónde falla realmente\n\nCon cutoff 0.253098, hay **120 false positives** de prioridad y **296 false negatives**. Todos los FP están en la banda alta y todos los FN en la baja.\n\nPor sector, Industrial sí discrimina (N=434, AUC **0.616**, AP **0.318**, Lift@10 **1.401×**); Land, Office y Retail quedan esencialmente en AUC 0.5 / Lift 1.0.\n\nEl problema no es afinar el threshold: la segmentación es demasiado gruesa. La siguiente mejora exige **nuevas señales PIT**.\n"),
        md("### 5.6 Qué se intentó y por qué no reemplaza al champion\n\n| Familia | Resultado | Decisión |\n|---|---|---|\n| CatBoost generalista | Lift@10 0.826× en Codexway | **No promover** |\n| Specialist CatBoost / RF | competitivos bajo otro stack | evidencia auxiliar |\n| Multi-Head | útil como challenger | no canónico |\n| Trajectory | señal puntual en T2 | extensión T2 |\n| Dynamic Need | segmentación interpretable | auxiliar |\n| Clusters / matching pockets | pockets locales | requieren confirmación |\n| Semantic rules / LLM features | sin lift robusto | fuera del predictor |\n\nEl champion es pequeño porque varias alternativas más sofisticadas **no justificaron su promoción bajo el mismo estándar temporal**.\n"),
        md("### 6.0 Qué problema resuelve Inventory\n\nLead Quality y Inventory se separan porque responden preguntas distintas:\n\n| Componente | Pregunta | Reloj dominante | Error que evita |\n|---|---|---|---|\n| Lead Quality | ¿qué tan probable es que el lead avance? | información comercial observable en T1 | gastar capacidad en leads sin señal |\n| Inventory | ¿podemos atender razonablemente lo que pide? | catálogo + Availability observables al score | prometer oferta inexistente o castigar por falta de datos |\n| Opportunity | ¿qué tan atractiva y atendible es la oportunidad? | combinación de ambas señales | esconder dos objetivos diferentes en un único número |\n\nEsta separación es deliberada. El modelo de Quality final **no usa Availability ni selected-Spot matching**; por tanto Inventory puede actuar como segundo eje sin volver a contar la misma señal dentro del champion.\n\nLa afirmación estricta de point-in-time aplica a Availability. Para atributos del listing como precio y algunos campos físicos, el histórico completo no está versionado; por eso el matching histórico total se etiqueta como **condicional**, no como reconstrucción PIT perfecta.\n"),
        md("## 6. Inventory, Opportunity y fallback\n\n### 6.1 Disponibilidad point-in-time\n\nAvailability se une con un **backward as-of** estricto. Historia ausente o vieja significa **UNKNOWN, no UNAVAILABLE**, y se expresa como bounds lower/upper; jamás se rellena desde el futuro."),
        md("### 6.1.1 Candidate generation: del request a un conjunto defendible\n\nPara cada lead T1, el sistema construye candidatos antes de calcular cualquier score de Inventory:\n\n1. parte de Spots del mismo **sector + estado**;\n2. vuelve a incluir el Spot exacto solicitado;\n3. exige que el Spot ya existiera: created_at <= prediction_timestamp;\n4. exige compatibilidad de modalidad: rent/sale/both;\n5. usa la ubicación de la inquiry cuando existe; si no, cae a la preferencia del lead;\n6. calcula compatibilidad de área, precio y geografía;\n7. añade Availability con el último snapshot conocido hacia atrás.\n\nLa geografía se relaja de forma explícita:\n- mismo corredor: fit = **1.00**;\n- mismo municipio: **0.85**;\n- mismo estado: **0.65**.\n\nÁrea y precio usan una penalización simétrica basada en la razón candidato/deseado. El candidate match usa media geométrica, de modo que una incompatibilidad fuerte no quede escondida por otras señales altas.\n\nEl número de candidatos se conserva dentro de Inventory; no entra a Lead Quality porque su cobertura cambia materialmente con el tiempo.\n"),
        md("### 6.1.2 Availability: backward-as-of, frescura e incertidumbre\n\nPara cada Spot candidato se toma **el último snapshot con snapshot_date <= prediction_timestamp**. El control final reporta **0 violaciones de snapshots futuros**.\n\nSensibilidad de frescura:\n\n| Ventana | Snapshot fresco | Unknown / stale | Leads con algún candidato fresco |\n|---:|---:|---:|---:|\n| 7 días | 19.16% | 80.84% | 93.46% |\n| **30 días** | **57.09%** | **42.91%** | **98.34%** |\n| 90 días | 86.03% | 13.97% | 98.52% |\n\nTreinta días es una política operativa, no una verdad física.\n\nSi el snapshot falta o está stale:\n- availability lower = **0**;\n- availability upper = **1**;\n- estado = unknown_missing_or_stale.\n\nAsí, **UNKNOWN no se convierte en UNAVAILABLE**. La falta de observación permanece como incertidumbre explícita.\n"),
        md("### 6.1.3 De candidatos a serviceability lower/upper\n\nCada candidato conserva una vista conservadora y una potencial:\n\n- candidate_match_lower acredita sólo Availability defendible;\n- candidate_match_upper conserva potencial cuando Availability es desconocida o stale.\n\nEl Spot exacto se evalúa por separado de las alternativas. Para fallback se usan las **3 mejores alternativas** en la agregación interna y se aplica una penalización cuando existen pocas opciones.\n\nInventory Serviceability es el máximo entre el componente exacto y el componente fallback, conservando lower, upper, uncertainty width y confidence.\n\nAuditoría agregada:\n\n| Métrica | Resultado |\n|---|---:|\n| Serviceability lower promedio | **0.6936** |\n| Serviceability upper promedio | **0.8213** |\n| Ancho de incertidumbre promedio | **0.1277** |\n| Inventory confidence promedio | **0.5217** |\n| Spot exacto atendible | **45.64%** |\n| Spot exacto con Availability desconocida | **44.30%** |\n| Sin alternativa conocida | **2.38%** |\n| Sin alternativa potencial | **0.00%** |\n\nLa brecha lower→upper muestra cuánto depende la decisión de información todavía no confirmada.\n"),
        code("display(Image(filename=str(ROOT/'outputs/figures/availability_coverage.png')))\ndisplay(pd.read_csv(ROOT/'outputs/tables/inventory_freshness_sensitivity.csv').round(4))\ndisplay(read_json(Path('outputs/metrics/inventory_audit.json')))"),
        md("### 6.2 Trade-off central\n\nLos componentes se comparan sobre el mismo holdout. Como T1 no observa éxito de fallback, la comparación combinada es diagnóstico de ranking, no probabilidad calibrada de inventario."),
        code("system_metrics = pd.read_csv(ROOT/'outputs/metrics/system_score_metrics.csv')\npaired = pd.read_csv(ROOT/'outputs/metrics/system_score_paired_delta.csv')\ndisplay(system_metrics.round(4)); display(paired.round(4))"),
        md("<div class=\"spot2-callout spot2-warning\"><strong>Decisión conservadora.</strong> Inventory puede superar random en algún bound o corte de capacidad, pero no mejora de forma incremental a Quality sobre el proxy T1. Su gate permanece <strong>NO-GO</strong>.</div>"),
        md("### 6.2.1 Opportunity: valor absoluto sí, valor incremental de Inventory no\n\nSobre el mismo holdout T1:\n\n| Señal | ROC-AUC | PR-AUC | Brier | Lift@5 | Lift@10 | Recall@10 |\n|---|---:|---:|---:|---:|---:|---:|\n| Lead Quality | 0.5478 | 0.2391 | **0.1658** | **1.689×** | **1.689×** | **16.98%** |\n| Opportunity lower | 0.5119 | **0.2477** | 0.1707 | 1.589× | 1.370× | 13.77% |\n| Opportunity upper | 0.5235 | 0.2613 | 0.1695 | **1.809×** | 1.507× | 15.15% |\n\nOpportunity lower sí supera random:\n- Lift@10 = **1.370×**;\n- IC95% = **[1.078×, 1.690×]**.\n\nPero frente a Quality-only:\n- ΔROC-AUC = **−0.0359**, IC95% [−0.0696, −0.0011];\n- ΔLift@10 = **−0.3186×**, IC95% [−0.6252, −0.0125];\n- ΔRecall@10 = **−3.20 pp**, IC95% [−6.28, −0.13 pp];\n- ΔBrier = **+0.00494**, peor para T1;\n- ΔPR-AUC = +0.0086, con intervalo que cruza cero.\n\nPor eso **Opportunity absolute lift = GO**, mientras **Inventory incremental gate = NO-GO**.\n\nNo es una contradicción: T1 mide progreso comercial; Inventory introduce además serviceability.\n"),
        md("### 6.3 Política de dos ejes y alternativas\n\nQuality y Serviceability permanecen separados: verificar inventario incierto, buscar alternativas para demanda de calidad sin servicio y mantener el flujo estándar en el resto. El ranking conserva top-3 interno y muestra hasta cinco alternativas compatibles."),
        md("### 6.3.1 Reglas operativas de la política de dos ejes\n\nInventory se clasifica así:\n\n- **Uncertain** si confidence < 0.50 o uncertainty width > 0.20;\n- **Serviceable** si lower >= 0.75;\n- **Potential fallback** si upper >= 0.50;\n- **Low serviceability** en el resto.\n\nLa acción se deriva junto con Quality:\n\n| Quality | Inventory | Acción |\n|---|---|---|\n| High / Priority | Serviceable | work_if_model_gate_passes |\n| High / Priority | Uncertain | verify_inventory_first |\n| High / Priority | Potential fallback / Low | source_or_offer_fallback |\n| Standard | cualquiera | standard_workflow |\n\nUn lead de Quality alta con Inventory incierto **no es un mal lead**: es un caso que requiere verificar capacidad de atención antes de prometer una opción.\n"),
        code("policy = scores[['quality_band','serviceability_band','diagnostic_action','deployment_status']].value_counts().reset_index(name='leads')\ndisplay(policy.head(20))\nshow = ['lead_id','lead_quality_score_0_100','inventory_serviceability_lower','inventory_serviceability_upper','inventory_confidence','fallback_spot_ids','fallback_reason_codes']\ndisplay(scores[show].head(10))"),
        md("### 6.4 Caso real anotado: lead 6 de validación"),
        code("case = scores.query(\"lead_id == 6 and split == 'validation'\").iloc[0]\nfallback_ids = json.loads(case['fallback_spot_ids']) if isinstance(case['fallback_spot_ids'], str) else list(case['fallback_spot_ids'])\nassert case['diagnostic_action'] == 'source_or_offer_fallback'\nassert fallback_ids == [756, 2687, 439, 1605, 1999]\ndisplay(HTML(f'''<section class=\"spot2-case\"><h3>Lead 6 · decisión observable en T1</h3><div class=\"spot2-grid\"><div class=\"spot2-card\"><strong>{case.lead_quality_score_0_100:.2f}</strong><small>Quality / 100</small></div><div class=\"spot2-card\"><strong>{100*case.inventory_serviceability_lower:.2f}–{100*case.inventory_serviceability_upper:.2f}</strong><small>Inventory lower–upper</small></div><div class=\"spot2-card\"><strong>{100*case.opportunity_probability_lower:.2f}–{100*case.opportunity_probability_upper:.2f}</strong><small>Opportunity lower–upper</small></div><div class=\"spot2-card\"><strong>{case.diagnostic_action}</strong><small>acción diagnóstica</small></div></div><div class=\"spot2-meter\"><span style=\"width:{case.lead_quality_score_0_100:.2f}%\"></span></div><p><strong>Alternativas visibles:</strong> {', '.join(map(str, fallback_ids))}</p><p>La incertidumbre no se oculta: Opportunity conserva dos bounds y la acción deriva de Quality × Serviceability, no de una probabilidad única presentada como certeza.</p></section>'''))"),
        code("# Lógica simplificada y fiel al scorer\nquality = case.p_lead_quality\ninv_low = case.inventory_serviceability_lower\ninv_high = case.inventory_serviceability_upper\nopp_low, opp_high = quality * inv_low, quality * inv_high\naction = case.diagnostic_action\nvisible_fallbacks = fallback_ids[:5]\nassert abs(opp_low - case.opportunity_probability_lower) < 1e-12\nassert abs(opp_high - case.opportunity_probability_upper) < 1e-12\ndisplay({'opportunity_bounds': (round(opp_low, 4), round(opp_high, 4)),\n         'action': action, 'visible_fallbacks': visible_fallbacks})"),
        md("### 6.5 Profundidad de candidatos y cobertura de fallback\n\nCandidate depth cambia materialmente con el tiempo; por eso se mantiene fuera de Lead Quality. El fallback puede devolver NO_RESULT antes que violar hard constraints.\n"),
        code("inv_candidates = pd.read_parquet(ROOT/'outputs/abt/abt_inventory_candidates.parquet')\ndepth = inv_candidates.groupby('lead_id').size().rename('candidate_depth')\ndisplay(depth.describe(percentiles=[.1,.25,.5,.75,.9,.95]).to_frame())\nfallback_counts = scores['fallback_spot_ids'].apply(lambda x: len(json.loads(x)) if isinstance(x,str) and x.startswith('[') else 0)\ndisplay(fallback_counts.value_counts().sort_index().rename_axis('visible_fallbacks').to_frame('leads'))\n"),
        md("### 6.5.1 Qué demuestra fallback y qué todavía no puede demostrar\n\nEl sistema entrega hasta **5 alternativas visibles**, priorizando candidatos con lower positivo y completando con candidatos de potencial upper cuando hace falta. Cada alternativa conserva reason codes de geografía y Availability.\n\nSi no existe una alternativa defendible, la política acepta **NO_RESULT / lista vacía** antes que violar hard constraints.\n\nEl Spot históricamente visitado **no es un gold label limpio de recomendación**: el histórico no registra qué candidatos fueron mostrados, rechazados o siquiera visibles bajo la misma política.\n\nPor eso Coverage@K contra el Spot visitado es diagnóstico, no prueba causal de relevance.\n\nPara validar fallback de verdad se necesitan exposure logs:\n- alternativas mostradas y posición;\n- alternativa aceptada;\n- visita posterior;\n- cierre o valor comercial;\n- estado de Inventory al momento de exposición.\n\nHasta contar con esos datos, Inventory/Fallback es una política operativa defendible y auditable, **no un uplift causal demostrado**.\n"),
        md("## 7. Robustez, IA y producto\n\n### 7.1 Mapa de experimentos y decisiones\n\nEl modelo final es sencillo **después** de una investigación amplia, no por ausencia de alternativas. La regla de cierre fue promover sólo componentes que conservaran utilidad bajo el contrato temporal canónico T1, fueran observables en score_time y justificaran su complejidad.\n\n| Hipótesis | Qué se probó | Qué aprendimos | Decisión |\n|---|---|---|---|\n| Business rules | Positive-rate baseline y reglas comerciales simples | Sirven como referencia de mínima complejidad, pero no ordenan mejor que el champion | **Baseline, no final** |\n| Logistic baselines | Lead-only, broad Logistic y ablación de asked_visit | Más columnas no mejoraron el ranking; broad Logistic queda por debajo de random en Lift@10 | **No promover** |\n| CatBoost canónico | CatBoost sobre el contrato limpio T1 de Codexway | Lift@10 canónico 0.826×; la no linealidad no compensa el information set disponible | **No promover** |\n| Pooled CatBoost / especialistas CatBoost-RF | Modelos tabulares fuertes bajo contratos experimentales por etapa | Superaron a arquitecturas neuronales en rolling CV histórico, pero pertenecen a otro contrato y no sustituyen el benchmark final T1 | **Evidencia histórica / challenger** |\n| Shared backbone / Multi-Head | Representación compartida con heads T0/T1/T2 | Fue útil para descubrir heterogeneidad por etapa, pero dejó de justificar su complejidad frente a tabulares | **Challenger histórico** |\n| Trajectory / progression | Features estrictamente previas para T2 | Señal dependiente de arquitectura; AssessmentSol1 no confirmó estabilidad suficiente para despliegue | **Extensión futura T2** |\n| T0 | Cold-start al crear el lead | Señal débil y sensible a exposición/drift; no desplaza T1 | **Sensibilidad** |\n| T2 | Re-scoring posterior con historia observable | Puede contener señal, pero exige otro score_event y estado histórico adicional | **No mezclar con T1** |\n| Dynamic Need | Refinamiento T0→T1 de necesidad | Interpretable y con mejoras puntuales, sin mejora global robusta suficiente | **Auxiliar** |\n| Clustering por entidad | Persona, Need, Physical Space, Location, Broker | Mejoró interpretabilidad; el lift global siguió pequeño/incierto | **Segmentación, no score** |\n| Matching profiles | Lead × Spot × Broker, facetas y routing | Aparecen pockets locales, pero no una sinergia global confirmada | **Exploratorio / routing futuro** |\n| Inquiry Intent / Broker Supply | Facetas de intención y oferta del broker | Intent aprendía principalmente weekday; Broker Supply quedó demasiado desbalanceado | **Descartar como capa predictiva** |\n| Semantic rules | Reglas determinísticas sobre copy/atributos | Lift@10 histórico 1.267×→1.196×; delta no pasa gate | **Catalog/Inventory QA** |\n| LLM-derived features | Pilotos semánticos Rules-first + LLM residual | No demostraron lift incremental ni una razón para depender de API en scoring | **Fuera del predictor** |\n| Selected-Spot matching | Compatibilidad con el Spot elegido bajo contratos alternativos | Puede capturar información útil, pero el estado histórico mutable del listing limita la afirmación PIT total | **No incorporar al champion Codexway** |\n| Opportunity alternatives | Producto continuo, políticas de dos ejes y Actionability Gate de AssessmentSol1 | Distintos contratos producen distintas integraciones; Codexway conserva lower/upper y gate incremental NO-GO | **Codexway sigue siendo autoridad** |\n| Leakage stress tests | Internal score, información futura de inquiries, nearest Availability | Las métricas pueden inflarse o cambiar al usar información no disponible en T1 | **Diagnóstico, nunca selección** |\n\n### 7.1.1 Qué no funcionó y por qué también importa\n\nLos resultados negativos son parte central de la evidencia:\n\n- **CatBoost no gana bajo el contrato limpio T1.**\n- **Más features no garantizan mejor ranking**: lead-only, broad Logistic y semantic additions no justificaron promoción.\n- **Los especialistas cambian de ganador entre folds** bajo arquitecturas históricas; no existe una familia universal estable.\n- **Multi-Head** aportó aprendizaje sobre etapas, pero no justificó costo de serving, calibración y monitoreo.\n- **Trajectory** contiene señal en T2 sólo en ciertos stacks; no es una mejora universal.\n- **Dynamic Need** es interpretable, pero no demuestra una mejora global robusta.\n- **Inquiry Intent v1** aprende principalmente día de la semana y empeora el desempeño fuera de muestra.\n- **Broker Supply** no forma una segmentación suficientemente balanceada.\n- **Pockets de clusters/matching** pueden verse atractivos en discovery, pero no sobreviven como regla gobernada sin nueva cohorte independiente.\n- **Semantic rules y features LLM** no demuestran Lift incremental para Lead Quality.\n- **Inventory no demuestra valor incremental sobre el target T1**: el gate permanece NO-GO, aunque siga siendo útil para serviceability.\n- **Fallback carece de gold natural y exposure logs históricos**; su valor causal no puede inferirse retrospectivamente.\n\n### 7.1.2 Jerarquía de evidencia\n\nPara evitar mezclar resultados incompatibles:\n\n1. **Canónico Codexway:** contrato T1, champion, Availability backward-as-of, Opportunity lower/upper y gates finales.\n2. **Histórico bajo otro contrato:** Multi-Head, pooled/specialists, trajectory, matching profiles y otros experimentos por etapa.\n3. **Challenger:** alternativa plausible que no alcanzó el estándar de promoción.\n4. **Exploratorio:** clusters, pockets y semantic discovery.\n5. **Resultado negativo:** evidencia útil para cerrar líneas y reducir complejidad.\n6. **Hipótesis futura:** sólo reabrible con nueva fuente, nueva cohorte o experimento online.\n\nLa tabla ejecutada a continuación muestra la evidencia de perfiles/clusters conservada para análisis; **ninguna fila se usa como multiplicador productivo**."),
        code("display(pd.read_csv(ROOT/'outputs/tables/cluster_profile_metrics.csv').round(4))\ndisplay(pd.read_csv(ROOT/'outputs/tables/cluster_combinations.csv').head(15))"),
        md("### 7.2 Leakage stress test — por qué una métrica alta puede ser falsa\n\nEl control temporal no se limita a una lista de columnas prohibidas. Se probaron deliberadamente variantes inválidas para demostrar qué ocurre cuando el modelo recibe información que **no existía en score_time**.\n\n| Variante | Qué viola | Resultado observable | Interpretación |\n|---|---|---|---|\n| Clean selected | Contrato T1 válido | ROC-AUC 0.5478 · Lift@10 1.689× | Referencia desplegable |\n| S001 lead_score_internal | Procedencia desconocida / potencial target leakage | Lift@10 0.822× | Una señal interna opaca no se acepta aunque existiera |\n| S002 future inquiry information | Usa eventos posteriores a T1 | ROC-AUC 0.8257 · PR-AUC 0.5519 · Lift@10 2.985× | **Inflado por futuro; no desplegable** |\n| S003 nearest Availability | Permite elegir snapshot futuro | 43.54% de joins usan futuro | Join temporal inválido |\n\n#### Qué información futura puede inflar el resultado\n\n- **Inquiries posteriores:** en T1 todavía no existen; introducirlas convierte trayectoria futura en predictor retrospectivo.\n- **Broker response / broker_response_hours de la inquiry actual:** ocurren después del score; no pueden explicar una decisión que debe tomarse antes de responder.\n- **Nearest Availability:** “el snapshot más cercano” puede estar después del score. La única semántica defendible es **último snapshot conocido hacia atrás**.\n- **Estado mutable actual del listing:** precio, status, counters, copy o atributos editables pueden haber cambiado; sin effective_time histórico no existe una reconstrucción PIT completa.\n- **Market Context:** un mes o periodo agregado no implica que el dato estuviera publicado y disponible ese día. Sin publication/effective time se usa para EDA, no como feature histórica.\n- **lead_score_internal:** aunque sea observable en el archivo, su construcción no es transparente; se bloquea para evitar reciclar señal downstream o target-derived.\n\nLa lección del stress test es deliberadamente simple:\n\n> **Una métrica alta obtenida con información que no existía en score_time no representa capacidad predictiva desplegable.**\n\nPor eso Codexway prefiere un Lift menor pero temporalmente defendible a un resultado espectacular producido por look-ahead."),
        code("display(read_json(Path('outputs/metrics/leakage_stress_test.json')))"),
        md("### 7.3 IA con alcance acotado: Catalog QA, no motor de priorización\n\n**El modelo de priorización no depende de un LLM.** La IA se ubica fuera del camino crítico del score y se propone como una capa de calidad y descubrimiento semántico del catálogo.\n\n#### Qué recibe\n\nPor listing, el auditor recibe únicamente el copy humano y los campos estructurados necesarios para contrastarlo: tipo/sector, atributos físicos relevantes y valores que puedan entrar en contradicción con el texto. No necesita outcomes comerciales ni información futura del lead.\n\n#### Qué produce\n\nUn output estructurado con:\n\n- status de calidad;\n- tipo de issue;\n- campo afectado;\n- fragmento mínimo de evidencia textual;\n- confianza / necesidad de revisión;\n- abstención cuando la evidencia no es suficiente.\n\nBusca principalmente:\n\n- **contradiction:** texto y campo estructurado no pueden ser simultáneamente ciertos;\n- **semantic_cross_field_mismatch:** el copy describe un uso o configuración materialmente distinto;\n- **unsupported_claim / not_verifiable / ambiguous:** señales que requieren revisión, pero no deben convertirse automáticamente en “error confirmado”.\n\n#### Cómo se gobierna\n\n- Rules-first: lo determinístico se resuelve sin pagar LLM.\n- Structured Outputs / schema versionado.\n- Prompt y schema hasheados.\n- No navegación ni hechos externos.\n- No corrección inventada.\n- Abstención permitida.\n- Cola humana para los casos accionables.\n- Sin dependencia runtime del score principal.\n- Privacidad y opt-in antes de enviar inventario natural a un proveedor externo.\n\n#### Evidencia disponible y lo que todavía falta\n\nHay dos tipos de evidencia que deben mantenerse separados:\n\n1. **Piloto histórico E017 sobre listings reales:** usó una estrategia Rules-first + LLM residual; no encontró señal semántica nueva suficiente para promover features LLM al ABT. Su valor fue cerrar la hipótesis predictiva y convertir patrones reutilizables en QA determinístico.\n2. **Evaluador Codexway actual:** conserva un benchmark **controlado/sintético** con contradicciones inyectadas y el prompt/schema congelados. En 40 casos fabricados el output fue schema-valid y detectó los casos diseñados, pero esto sólo valida comportamiento de tarea/sensibilidad.\n\nEn la evaluación natural actual:\n- human gold = **0**;\n- la corrida natural está marcada como no enviada sin opt-in de privacidad;\n- por tanto **no existe human precision/recall natural defendible**.\n\nLa accuracy/precision perfecta sobre casos inyectados **no es prueba de precisión real en producción**. El siguiente requisito científico es un gold humano ciego, muestreado sobre listings naturales y con adjudicación de desacuerdos.\n\nEl prompt exacto versionado se conserva a continuación como parte del artefacto técnico."),
        code("llm = read_json(Path('outputs/metrics/llm_audit_evaluation.json')); display(llm)"),
        md("#### Prompt LLM versionado\n\n# Semantic Inventory Quality Auditor\n\nYou are a conservative data-quality auditor for commercial real-estate inventory.\nYour task is to compare the human-facing copy of one listing with the structured\nfields supplied in the same payload. Do not browse, infer external facts, or\nrewrite the listing.\n\nReport an issue only when the copy itself provides specific evidence. Distinguish:\n\n- `contradiction`: text and a structured value cannot both be true;\n- `semantic_cross_field_mismatch`: the copy describes a materially different\n  property use or physical configuration than the structured record;\n- `unsupported_claim`: the text makes a claim that the supplied fields cannot\n  verify;\n- `not_verifiable`: verification would require information outside the payload;\n- `ambiguous`: the language supports more than one reasonable reading.\n\nOnly `contradiction` and `semantic_cross_field_mismatch` are actionable for the\nautomated QA queue. Unsupported, unverifiable, or ambiguous wording must not be\npromoted as a confirmed data error. Quote the shortest exact evidence fragment.\nNever manufacture a correction. If evidence is insufficient, abstain.\n\nReturn only an object conforming to the supplied JSON Schema. Set\n`quality_status` to `critical` only for a high-confidence, material actionable\nissue; use `review` for weaker or non-actionable concerns; otherwise use `good`.\n\n"),
        md("### 7.4 Diseño experimental final — validar antes de automatizar\n\nLas métricas actuales son offline y observacionales. El orden correcto de validación es:\n\n1. **Abrir una nueva cohorte forward** que no haya sido usada en discovery.\n2. Ejecutar **shadow scoring** sin alterar la operación.\n3. Esperar la **madurez completa del target** antes de juzgar Quality.\n4. Revisar **estabilidad de Lead Quality**: prevalence, Lift/Recall@K, Brier, calibración y composición.\n5. Revisar **salud de Inventory**: coverage, stale/unknown, uncertainty y candidate depth.\n6. Verificar que **Opportunity** mantenga un comportamiento operativo razonable y que los guards no se disparen de forma anómala.\n7. Sólo entonces ejecutar un **experimento controlado**.\n\n#### Piloto recomendado\n\n- randomized;\n- asignación **sticky por lead_id**;\n- análisis **intention-to-treat**;\n- logging explícito de exposición;\n- stratification/guardrails donde corresponda;\n- control de SRM, interferencia y carga comercial;\n- posibilidad de rollback.\n\n#### Métricas del piloto, separadas por objetivo\n\n**Funnel**\n- scheduled_visit;\n- visita efectivamente realizada;\n- cierre / outcome comercial cuando exista.\n\n**Fallback**\n- fallback mostrado;\n- fallback aceptado;\n- posición de la alternativa;\n- NO_RESULT.\n\n**Operación**\n- tiempo de respuesta;\n- carga por broker/equipo;\n- volumen de leads priorizados;\n- verificación manual de inventario.\n\n**Experiencia**\n- abandono;\n- repetición de búsqueda;\n- señales de fricción o queja.\n\nLa métrica offline actual **no es uplift causal**. Sólo un RCT con exposición correctamente instrumentada puede responder si la política cambia resultados frente al proceso actual."),
        code("display(read_json(Path('outputs/tables/online_ab_protocol.json')))"),
        md("## 8. Producción, gobierno y trazabilidad\n\n### 8.1 Arquitectura end-to-end\n\nLa solución de producto separa un evento histórico de scoring de los componentes que pueden refrescarse operativamente:\n\n\\`lead created\\`\n→ \\`first inquiry persisted\\`\n→ \\`T1 feature assembly\\`\n→ \\`Lead Quality\\`\n→ \\`Inventory backward-as-of\\`\n→ \\`fallback\\`\n→ \\`Opportunity lower/upper\\`\n→ \\`decision policy\\`\n→ \\`event logging\\`\n→ \\`monitoring\\`\n\n#### Regla temporal de serving\n\n- **p_quality_T1 queda fijo** para el score_event histórico T1. No se reescribe porque después cambie el catálogo.\n- **Inventory sí puede refrescarse operativamente** para decidir qué se puede atender ahora.\n- Un refresh de Inventory genera una nueva observación operacional, **no una mutación retroactiva** del score T1.\n- Un futuro T2 debe crearse como **nuevo score_event** con su propio timestamp, features y versión; nunca sobrescribe T1.\n- Availability histórica conserva backward-as-of; UNKNOWN sigue siendo distinto de UNAVAILABLE.\n\n### 8.2 Contrato de versionamiento\n\nCada score_event debe persistir como mínimo:\n\n| Campo | Para qué sirve |\n|---|---|\n| lead_id / score_event_id | Identidad y reconstrucción |\n| score_time | Reloj de decisión |\n| scoring_stage | T0, T1, T2 u otro contrato |\n| model_version | Champion exacto usado |\n| feature_policy_version | Allowlist/denylist y transformaciones |\n| inventory_policy_version | Backward-as-of, freshness, bounds |\n| threshold_capacity_version | Top-K/capacidad y política tie-aware |\n| fallback_policy_version | Hard constraints, top-3 interno, visibles y NO_RESULT |\n| p_quality | Señal fija del evento |\n| inventory_lower / upper / confidence | Estado observable de serviceability |\n| opportunity_lower / upper | Combinación preservando incertidumbre |\n| decision_action | Acción derivada |\n| event_created_at / refreshed_at | Auditoría de persistencia y refresh |\n\n### 8.3 Monitoreo por componente\n\n#### Lead Quality\n- prevalence;\n- PR-AUC;\n- Lift@5/10/20;\n- Recall@5/10/20;\n- Brier y Log Loss;\n- calibration / reliability;\n- estabilidad mensual;\n- PSI o drift de la variable final;\n- composición por sector y source;\n- proporción de scores empatados / bandas.\n\n#### Inventory\n- Availability coverage;\n- snapshot age;\n- fresh / stale / unknown;\n- serviceability lower / upper;\n- uncertainty width;\n- confidence;\n- candidate depth;\n- fallback Coverage@K como diagnóstico;\n- número de recomendaciones visibles;\n- NO_RESULT;\n- cambios de cobertura histórica y violations = 0.\n\n#### Opportunity\n- distribución lower / upper;\n- Lift@K sobre el objetivo declarado;\n- delta vs Quality-only;\n- Priority con Inventory incierto;\n- share serviceable;\n- fallback usage;\n- guardrails comerciales y volumen por acción.\n\n#### IA / Catalog QA\n- contradiction rate;\n- human precision;\n- false positives / false negatives;\n- drift del catálogo;\n- costo y latencia;\n- schema-valid rate;\n- abstention rate;\n- tasa de escalamiento a revisión humana.\n\n### 8.4 Gobierno y rollback\n\nEl champion no cambia por una mejora puntual aislada. Una nueva versión debe pasar controles temporales, reproducibilidad, métricas de capacidad y revisión de leakage. El rollback debe regresar a la última versión conocida de modelo, feature policy, Inventory policy y fallback policy como un conjunto versionado."),
        code("display(read_json(Path('outputs/metrics/deployment_readiness.json')))\ndisplay(read_json(Path('outputs/tables/online_ab_protocol.json')))\n"),
        md("### 8.5 Evidencia y artefactos canónicos\n\nLa trazabilidad final se apoya en artefactos generados por el pipeline, no en claims sueltos:\n\n- \\`evidence/LEAKAGE_MATRIX.md\\` — señales permitidas, bloqueadas y condicionales.\n- \\`evidence/DECISIONS.md\\` — decisiones metodológicas congeladas.\n- \\`evidence/TRACEABILITY.md\\` — relación entre claims y outputs.\n- \\`outputs/metrics/t1_model_metrics.json\\` — champion, calibración y benchmark.\n- \\`outputs/metrics/system_evaluation.json\\` — gates de Quality, Opportunity e Inventory incremental.\n- \\`outputs/metrics/leakage_stress_test.json\\` — variantes inválidas controladas.\n- \\`outputs/metrics/llm_audit_evaluation.json\\` — estado real de la evaluación IA.\n- \\`outputs/predictions/lead_opportunity_scores.parquet\\` — salida operacional por lead.\n- \\`entregable/**\\` — narrativa final en español.\n\nLa celda ejecutada siguiente verifica que los artefactos críticos existan antes de cerrar el notebook. El principio de gobierno es que **una conclusión debe poder rastrearse a un output, una decisión congelada o una limitación explícita**."),
        code("artifacts = [\n ROOT/'outputs/predictions/lead_opportunity_scores.parquet',\n ROOT/'outputs/metrics/t1_model_metrics.json',\n ROOT/'outputs/metrics/system_evaluation.json',\n ROOT/'outputs/tables/error_analysis.csv',\n ROOT/'evidence/LEAKAGE_MATRIX.md',\n ROOT.parent/'entregable/01_eda/EDA_FINAL.md',\n ROOT.parent/'entregable/03_lead_quality/MODELO_CALIDAD_LEAD.md',\n ROOT.parent/'entregable/05_opportunity_produccion/01_LEAD_OPPORTUNITY_SCORE.md',\n]\nartifact_check = pd.DataFrame({'artifact':[str(p.relative_to(ROOT.parent)) for p in artifacts],\n                               'exists':[p.exists() for p in artifacts]})\nassert artifact_check['exists'].all()\ndisplay(artifact_check)\n"),
        md("## 9. Conclusiones y reproducción\n\n### 9.1 Conclusión final\n\n> **Spot2 no enfrenta un solo problema de scoring. Hay que separar la posibilidad de que un lead avance de la posibilidad de atenderlo con el inventario observable en ese momento.**\n\nLa evidencia final soporta una arquitectura deliberadamente separada:\n\n- **Lead Quality** aporta señal de priorización en T1: Lift@10 = **1.689×**, IC95% **[1.381×, 1.982×]**.\n- **Inventory** convierte prioridad en una decisión de atención mediante Availability backward-as-of, lower/upper, confidence y uncertainty.\n- **Fallback** evita que la indisponibilidad o incertidumbre del Spot original termine automáticamente en abandono; usa top-3 interno, hasta cinco visibles y acepta NO_RESULT.\n- **Opportunity** combina ambas señales sin ocultarlas: lower = p_quality × serviceability_lower y upper = p_quality × serviceability_upper.\n- **Opportunity lower** supera random en Lift@10 (**1.370×**, IC95% **[1.078×, 1.690×]**), pero **no supera Quality-only para el target T1**; por eso Inventory incremental permanece **NO-GO**.\n- **IA** agrega una capa de Catalog QA y semantic discovery; **no es dependencia predictiva del score principal**.\n- El siguiente paso correcto es **forward shadow validation → experimento controlado**, no automatización inmediata.\n\nLa simplicidad del champion es una decisión metodológica: se investigaron reglas, modelos no lineales, especialistas, multi-head, trajectory, matching, clusters y semántica; ninguno justificó desplazar la solución final bajo el contrato canónico actual."),
        md("### 9.2 Limitaciones finales\n\nEstas limitaciones son parte de la conclusión, no notas al pie:\n\n1. **El target es un early-funnel proxy** (\\`scheduled_visit\\`), no cierre ni revenue.\n2. **El holdout es procedural, no completamente pristine**: el dataset global ya fue inspeccionado durante el proceso.\n3. **Lead Quality tiene baja resolución**: después de calibración concentra esencialmente dos niveles de score.\n4. **Los rolling folds son heterogéneos**: 2/4 superan random en Lift@10 y existen periodos débiles.\n5. **El estado histórico completo del listing no está versionado**: precio y ciertos atributos mutables no permiten afirmar PIT total.\n6. **Availability coverage cambia materialmente con el tiempo**, por lo que freshness/unknown son riesgo operacional real.\n7. **Fallback no tiene gold natural limpio**: el Spot visitado histórico no equivale a recomendación expuesta.\n8. **No existen exposure logs históricos completos** para saber qué alternativas se mostraron, aceptaron o rechazaron.\n9. **Inventory incremental gate = NO-GO sobre T1**: no mejora el ranking del proxy de visita frente a Quality-only.\n10. **El LLM no tiene todavía gold humano ciego suficiente** para estimar precisión/recall natural.\n11. **Los resultados offline son observacionales** y pueden reflejar selección histórica.\n12. **No existe evidencia causal de uplift** de la política completa.\n\nEstas limitaciones no invalidan el trabajo; delimitan con precisión qué está demostrado y qué requiere nueva evidencia."),
        md("### 9.3 Cómo reproducir la solución\n\nDesde la raíz del repositorio, la ruta canónica existente es:\n\n\\`python codexway/scripts/run_all.py --skip-live-llm\\`\n\nEl runner:\n\n1. audita las fuentes y contratos temporales;\n2. construye ABTs;\n3. ejecuta feature engineering registrado;\n4. entrena/calibra los modelos canónicos;\n5. genera predicciones de Lead Quality, Inventory y Opportunity;\n6. calcula métricas, intervalos, gates y stress tests;\n7. escribe tablas y figuras;\n8. actualiza evidencias;\n9. regenera \\`codexway/notebooks/spot2_assessment.ipynb\\`;\n10. regenera \\`codexway/notebooks/spot2_assessment.html\\`;\n11. verifica reproducibilidad/fingerprints donde aplica.\n\n\\`--skip-live-llm\\` evita llamadas externas durante la reproducción; la evidencia IA controlada/cached y su prompt versionado permanecen auditables.\n\n#### Sanity check de cierre\n\nLa última celda ejecutada verifica el contrato esencial del sistema: champion T1, Quality gate, Inventory incremental NO-GO, Opportunity absolute GO y consistencia del caso de fallback. El empaquetador final agrega además controles de encabezados IPYNB↔HTML, contador de celdas y equivalencia byte-a-byte de notebook/HTML dentro del ZIP."),
        code("required = {\n  'T1': model['selected_model'] == 'stable_segment_logistic',\n  'quality_gate': system['lead_quality_gate'] == 'GO',\n  'inventory_incremental': system['inventory_incremental_gate'] == 'NO_GO',\n  'opportunity_absolute': system['opportunity_absolute_lift_gate'] == 'GO',\n  'case_action': case.diagnostic_action == 'source_or_offer_fallback',\n  'five_visible_fallbacks': len(fallback_ids) == 5,\n}\nassert all(required.values())\ndisplay(HTML('<div class=\"spot2-callout\"><strong>Contrato final verificado.</strong> ' + ' · '.join(f'{k}: ✓' for k in required) + '</div>'))"),
    ]

    notebook = nbformat.v4.new_notebook(
        cells=cells,
        metadata={
            "kernelspec": {"display_name": "Python 3", "language": "python", "name": "python3"},
            "language_info": {"name": "python", "version": "3"},
            "title": "Spot2 · Lead Opportunity Score · Assessment ejecutivo",
            "authors": [{"name": "Spot2 / Codexway"}],
            "spot2": {"audience": "Evaluador, Producto y C-Level", "contract": "T1_first_inquiry"},
        },
    )
    ipynb = notebook_dir / "spot2_assessment.ipynb"
    nbformat.write(notebook, ipynb)
    executed = NotebookClient(
        notebook,
        timeout=600,
        kernel_name="python3",
        resources={"metadata": {"path": str(root)}},
    ).execute()
    nbformat.write(executed, ipynb)

    exporter = HTMLExporter()
    exporter.exclude_input_prompt = True
    exporter.exclude_output_prompt = True
    html, _ = exporter.from_notebook_node(executed)
    html_path = notebook_dir / "spot2_assessment.html"
    html_path.write_text(_executive_html(html), encoding="utf-8")
    return ipynb, html_path
